package com.camerastreamingapp.ui.screens

import androidx.compose.foundation.background
import androidx.compose.foundation.clickable\nimport androidx.compose.foundation.layout.*\nimport androidx.compose.foundation.lazy.LazyColumn\nimport androidx.compose.foundation.lazy.items\nimport androidx.compose.material3.*\nimport androidx.compose.runtime.*\nimport androidx.compose.ui.Modifier\nimport androidx.compose.ui.graphics.Color\nimport androidx.compose.ui.unit.dp\nimport com.camerastreamingapp.data.models.Camera\nimport com.camerastreamingapp.data.models.ConnectionStatus\nimport com.camerastreamingapp.ui.viewmodel.CameraStreamingViewModel\n\n/**\n * Camera list and streaming UI screen\n */\n@Composable\nfun CameraStreamingScreen(\n    viewModel: CameraStreamingViewModel,\n    modifier: Modifier = Modifier\n) {\n    val cameras by viewModel.cameras.collectAsState()\n    val selectedCamera by viewModel.selectedCamera.collectAsState()\n    val connectionStatus by viewModel.connectionStatus.collectAsState()\n    val isLoading by viewModel.isLoading.collectAsState()\n    val errorMessage by viewModel.errorMessage.collectAsState()\n\n    Column(\n        modifier = modifier\n            .fillMaxSize()\n            .background(Color(0xFF1a1a1a))\n    ) {\n        // Top bar\n        CameraStreamingTopBar()\n\n        if (selectedCamera != null) {\n            // Stream view when camera selected\n            CameraStreamView(\n                camera = selectedCamera!!,\n                connectionStatus = connectionStatus,\n                isLoading = isLoading,\n                onDisconnect = { viewModel.disconnectFromCamera() },\n                modifier = Modifier\n                    .weight(1f)\n                    .fillMaxWidth()\n            )\n        } else {\n            // Camera list when no camera selected\n            CameraListView(\n                cameras = cameras,\n                onCameraSelected = { viewModel.connectToCamera(it) },\n                modifier = Modifier\n                    .weight(1f)\n                    .fillMaxWidth()\n            )\n        }\n\n        // Error message\n        if (errorMessage != null) {\n            ErrorBanner(\n                message = errorMessage!!,\n                onDismiss = { viewModel.clearError() }\n            )\n        }\n\n        // Bottom controls\n        CameraControlPanel(\n            connectionStatus = connectionStatus,\n            modifier = Modifier.fillMaxWidth()\n        )\n    }\n}\n\n/**\n * Top bar component\n */\n@Composable\nfun CameraStreamingTopBar() {\n    TopAppBar(\n        title = { Text(\"IP Camera Streaming\", color = Color.White) },\n        colors = TopAppBarDefaults.topAppBarColors(\n            containerColor = Color(0xFF0d0d0d)\n        )\n    )\n}\n\n/**\n * Camera stream view component\n */\n@Composable\nfun CameraStreamView(\n    camera: Camera,\n    connectionStatus: ConnectionStatus,\n    isLoading: Boolean,\n    onDisconnect: () -> Unit,\n    modifier: Modifier = Modifier\n) {\n    Column(\n        modifier = modifier\n            .padding(16.dp)\n            .background(Color(0xFF2a2a2a), shape = RoundedCornerShape(8.dp))\n            .padding(16.dp)\n    ) {\n        // Camera name and status\n        Row(\n            modifier = Modifier\n                .fillMaxWidth()\n                .padding(bottom = 16.dp),\n            horizontalArrangement = Arrangement.SpaceBetween\n        ) {\n            Column {\n                Text(\n                    text = camera.name,\n                    style = MaterialTheme.typography.headlineSmall,\n                    color = Color.White\n                )\n                Text(\n                    text = camera.ipAddress,\n                    style = MaterialTheme.typography.bodySmall,\n                    color = Color.Gray\n                )\n            }\n\n            ConnectionStatusBadge(status = connectionStatus)\n        }\n\n        // Stream view placeholder (ExoPlayer would go here)\n        Box(\n            modifier = Modifier\n                .fillMaxWidth()\n                .height(300.dp)\n                .background(Color.Black, shape = RoundedCornerShape(8.dp)),\n            contentAlignment = androidx.compose.ui.Alignment.Center\n        ) {\n            if (isLoading) {\n                CircularProgressIndicator(color = Color.White)\n            } else if (connectionStatus == ConnectionStatus.CONNECTED) {\n                Text(\"Stream Preview\", color = Color.Gray)\n            } else {\n                Text(connectionStatus.name, color = Color.Gray)\n            }\n        }\n\n        // PTZ Controls (Pan/Tilt/Zoom)\n        PTZControls(\n            modifier = Modifier\n                .fillMaxWidth()\n                .padding(top = 16.dp)\n        )\n\n        // Action buttons\n        Row(\n            modifier = Modifier\n                .fillMaxWidth()\n                .padding(top = 16.dp),\n            horizontalArrangement = Arrangement.spacedBy(8.dp)\n        ) {\n            Button(\n                onClick = onDisconnect,\n                modifier = Modifier.weight(1f),\n                colors = ButtonDefaults.buttonColors(\n                    containerColor = Color(0xFFd32f2f)\n                )\n            ) {\n                Text(\"Disconnect\")\n            }\n\n            Button(\n                onClick = { /* Start recording */ },\n                modifier = Modifier.weight(1f),\n                colors = ButtonDefaults.buttonColors(\n                    containerColor = Color(0xFF388e3c)\n                )\n            ) {\n                Text(\"Record\")\n            }\n        }\n    }\n}\n\n/**\n * Camera list view component\n */\n@Composable\nfun CameraListView(\n    cameras: List<Camera>,\n    onCameraSelected: (Camera) -> Unit,\n    modifier: Modifier = Modifier\n) {\n    Column(\n        modifier = modifier\n            .padding(16.dp)\n    ) {\n        Text(\n            text = \"Select Camera\",\n            style = MaterialTheme.typography.headlineSmall,\n            color = Color.White,\n            modifier = Modifier.padding(bottom = 16.dp)\n        )\n\n        if (cameras.isEmpty()) {\n            Text(\n                text = \"No cameras configured\",\n                color = Color.Gray,\n                modifier = Modifier.padding(16.dp)\n            )\n        } else {\n            LazyColumn(\n                verticalArrangement = Arrangement.spacedBy(8.dp)\n            ) {\n                items(cameras) { camera ->\n                    CameraListItem(\n                        camera = camera,\n                        onClick = { onCameraSelected(camera) }\n                    )\n                }\n            }\n        }\n    }\n}\n\n/**\n * Camera list item component\n */\n@Composable\nfun CameraListItem(\n    camera: Camera,\n    onClick: () -> Unit\n) {\n    Card(\n        modifier = Modifier\n            .fillMaxWidth()\n            .clickable(onClick = onClick),\n        colors = CardDefaults.cardColors(\n            containerColor = Color(0xFF2a2a2a)\n        )\n    ) {\n        Column(\n            modifier = Modifier\n                .fillMaxWidth()\n                .padding(16.dp)\n        ) {\n            Text(\n                text = camera.name,\n                style = MaterialTheme.typography.titleMedium,\n                color = Color.White\n            )\n            Text(\n                text = \"${camera.ipAddress}:${camera.port}\",\n                style = MaterialTheme.typography.bodySmall,\n                color = Color.Gray,\n                modifier = Modifier.padding(top = 4.dp)\n            )\n        }\n    }\n}\n\n/**\n * Connection status badge component\n */\n@Composable\nfun ConnectionStatusBadge(\n    status: ConnectionStatus,\n    modifier: Modifier = Modifier\n) {\n    val backgroundColor = when (status) {\n        ConnectionStatus.CONNECTED -> Color(0xFF388e3c)\n        ConnectionStatus.CONNECTING -> Color(0xFFf57c00)\n        ConnectionStatus.RECONNECTING -> Color(0xFFf57c00)\n        ConnectionStatus.DISCONNECTED -> Color(0xFF757575)\n        ConnectionStatus.ERROR -> Color(0xFFd32f2f)\n    }\n\n    Surface(\n        modifier = modifier,\n        color = backgroundColor,\n        shape = RoundedCornerShape(4.dp)\n    ) {\n        Text(\n            text = status.name,\n            color = Color.White,\n            style = MaterialTheme.typography.labelSmall,\n            modifier = Modifier.padding(8.dp)\n        )\n    }\n}\n\n/**\n * PTZ (Pan/Tilt/Zoom) controls component\n */\n@Composable\nfun PTZControls(\n    modifier: Modifier = Modifier\n) {\n    Column(\n        modifier = modifier\n    ) {\n        Text(\n            text = \"PTZ Controls\",\n            style = MaterialTheme.typography.bodySmall,\n            color = Color.Gray,\n            modifier = Modifier.padding(bottom = 8.dp)\n        )\n\n        // Directional controls\n        Column(\n            modifier = Modifier.fillMaxWidth(),\n            horizontalAlignment = androidx.compose.ui.Alignment.CenterHorizontally\n        ) {\n            // Up\n            Button(\n                onClick = { /* Pan up */ },\n                modifier = Modifier.size(40.dp),\n                contentPadding = PaddingValues(0.dp)\n            ) {\n                Text(\"↑\")\n            }\n\n            // Left, Right\n            Row(\n                modifier = Modifier\n                    .fillMaxWidth()\n                    .padding(vertical = 4.dp),\n                horizontalArrangement = Arrangement.Center,\n                verticalAlignment = androidx.compose.ui.Alignment.CenterVertically\n            ) {\n                Button(\n                    onClick = { /* Pan left */ },\n                    modifier = Modifier.size(40.dp),\n                    contentPadding = PaddingValues(0.dp)\n                ) {\n                    Text(\"←\")\n                }\n\n                Spacer(modifier = Modifier.width(8.dp))\n\n                Button(\n                    onClick = { /* Pan right */ },\n                    modifier = Modifier.size(40.dp),\n                    contentPadding = PaddingValues(0.dp)\n                ) {\n                    Text(\"→\")\n                }\n            }\n\n            // Down\n            Button(\n                onClick = { /* Pan down */ },\n                modifier = Modifier.size(40.dp),\n                contentPadding = PaddingValues(0.dp)\n            ) {\n                Text(\"↓\")\n            }\n        }\n\n        // Zoom controls\n        Row(\n            modifier = Modifier\n                .fillMaxWidth()\n                .padding(top = 8.dp),\n            horizontalArrangement = Arrangement.spacedBy(8.dp)\n        ) {\n            Button(\n                onClick = { /* Zoom in */ },\n                modifier = Modifier.weight(1f)\n            ) {\n                Text(\"Zoom In\")\n            }\n\n            Button(\n                onClick = { /* Zoom out */ },\n                modifier = Modifier.weight(1f)\n            ) {\n                Text(\"Zoom Out\")\n            }\n        }\n    }\n}\n\n/**\n * Camera control panel at bottom\n */\n@Composable\nfun CameraControlPanel(\n    connectionStatus: ConnectionStatus,\n    modifier: Modifier = Modifier\n) {\n    Surface(\n        modifier = modifier,\n        color = Color(0xFF0d0d0d),\n        shadowElevation = 4.dp\n    ) {\n        Row(\n            modifier = Modifier\n                .fillMaxWidth()\n                .padding(16.dp),\n            horizontalArrangement = Arrangement.spacedBy(8.dp)\n        ) {\n            Button(\n                onClick = { /* Settings */ },\n                modifier = Modifier.weight(1f)\n            ) {\n                Text(\"Settings\")\n            }\n\n            Button(\n                onClick = { /* Recordings */ },\n                modifier = Modifier.weight(1f)\n            ) {\n                Text(\"Recordings\")\n            }\n\n            Button(\n                onClick = { /* Add Camera */ },\n                modifier = Modifier.weight(1f)\n            ) {\n                Text(\"Add\")\n            }\n        }\n    }\n}\n\n/**\n * Error banner component\n */\n@Composable\nfun ErrorBanner(\n    message: String,\n    onDismiss: () -> Unit\n) {\n    Surface(\n        modifier = Modifier.fillMaxWidth(),\n        color = Color(0xFFd32f2f)\n    ) {\n        Row(\n            modifier = Modifier\n                .fillMaxWidth()\n                .padding(16.dp),\n            horizontalArrangement = Arrangement.SpaceBetween,\n            verticalAlignment = androidx.compose.ui.Alignment.CenterVertically\n        ) {\n            Text(\n                text = message,\n                color = Color.White,\n                modifier = Modifier.weight(1f)\n            )\n\n            IconButton(onClick = onDismiss) {\n                Text(\"✕\", color = Color.White)\n            }\n        }\n    }\n}\n